// The selection of the editor's side of ControlUiBridge: ui.setSelection (Control/Ops/SelectionOps.cpp) selects a clip
// or a track through the arrangement view as a click does, and opens a clip as a double click does. What the
// selection brings about besides (notes generated by the piano roll, the scale of the transport bar) is the
// editor's own doing; the control API observes it.
#include "ControlEditorBridge.h"

#include "PluginEditor.h"

#include "Utils/ScaleUiMapping.h"

namespace OpenTune {

bool ControlEditorBridge::canSelect() const
{
    return true;
}

bool ControlEditorBridge::select(int trackId, std::uint64_t placementId, bool openEditor)
{
    if (trackId < 0 || trackId >= OpenTuneAudioProcessor::MAX_TRACKS)
        return false;
    if (placementId == 0) {
        // The track becomes the active track with no clip selected: applyPlacementSelectionContext() with no clip,
        // which the track panel shows and which leaves the piano roll empty. Then the arrangement view drops its
        // selection as a click on an empty area does (commitEmptyPlacementSelection).
        editor_.applyPlacementSelectionContext(trackId, 0);
        editor_.arrangementView_.commitControlSelection(trackId, 0);
        return true;
    }
    const int placementIndex = editor_.processorRef_.findPlacementIndexById(trackId, placementId);
    if (placementIndex < 0)
        return false;
    // ArrangementViewComponent::commitControlSelection() (the view's hook): a plain click on the clip, which the view
    // highlights, commits to the arrangement and reports to the editor (placementSelectionChanged: the piano roll
    // and the scale of the transport bar).
    editor_.arrangementView_.commitControlSelection(trackId, placementId);
    // The double click that follows opens the clip in the piano roll. It switches the workspace when the arrangement is
    // shown (placementDoubleClicked() checks isWorkspaceView_), which moves the keyboard focus (see
    // ControlEditorBridgeWorkspace.cpp). The changed mark is settled only for a double click that switches: with the
    // piano roll shown already nothing moves the focus, and a mark set by anything else stays.
    if (openEditor) {
        const bool switches = editor_.isWorkspaceView_;
        const auto baseline = viewSwitchBaseline();
        editor_.placementDoubleClicked(trackId, placementIndex);
        if (switches)
            settleViewSwitch(baseline);
    }
    return true;
}

std::optional<ControlUiBridge::UiScale> ControlEditorBridge::scaleForSelection(int trackId,
                                                                               std::uint64_t placementId) const
{
    // resolveScaleForPlacementContent(): the scale that applyResolvedScaleForPlacementContent() shows once the clip is
    // selected.
    const int placementIndex = editor_.processorRef_.findPlacementIndexById(trackId, placementId);
    if (placementIndex < 0)
        return std::nullopt;
    const auto key = editor_.resolveScaleForPlacementContent(trackId, placementIndex);
    UiScale scale;
    scale.rootNote = static_cast<int>(key.root);
    scale.scaleType = scaleToUiScaleType(key.scale);
    return scale;
}

} // namespace OpenTune
